-- ==========================================================================
--  Prospecting  |  NEXRIFT
-- ==========================================================================
--  UI 100% Nexrift: Dashboard, launcher, ukuran/skala window, dan tombol
--  buka/tutup semuanya bawaan lib (tanpa tab / ikon buatan sendiri).
--
--  Struktur:
--    Window  ->  Tab (per kategori)  ->  Accordion (per fitur)  ->  komponen
--
--  Tab dua kolom: Accordion(tab, judul, terbuka, kolom) dengan kolom 1 / 2.
--  Semua nilai tersimpan lewat Flag "prospecting.<fitur>.<nama>".
--  Logic game (mulai "MAIN CODE") tidak diubah.
-- ==========================================================================

local Nexrift = loadstring(game:HttpGet("https://raw.githubusercontent.com/dam45383-netizen/Loader/refs/heads/main/UI.lua"))()

local UserInputService = game:GetService("UserInputService")
local IS_MOBILE = UserInputService.TouchEnabled and not UserInputService.MouseEnabled

-- ================= PREREQUISITES (tanpa Loader) =================
-- Versi asli file ini minta dijalankan lewat Loader, yang ngedaftarin
-- TaskManager ke getgenv().__PrereqStorageRegistry.
-- Supaya file ini bisa dipaste langsung tanpa Loader, prereq-nya
-- di-download sendiri dari repo yang sama (dawnpetal/loader, sesuai
-- manifest Prospecting!) lalu di-load di sini. Hasilnya sama persis:
-- TaskManager jadi local dengan nama & isi yang sama seperti versi Loader.
-- ShoppingMart TIDAK di-download lagi: UI Shop sekarang NexriftShop (ada di
-- file ini), logic belanjanya sama persis dengan ShoppingMart.
--
-- Path prereq di manifest ("utils/TaskManager.lua") relatif ke folder
-- manifest (src/), BUKAN ke root repo -- jadi kandidat pertama adalah
-- src/utils/... (yang terbukti bisa). Kandidat lain disimpan sebagai
-- fallback, dan yang pertama berhasil langsung dipakai.
-- ================================================================

local function fetchFirst(urls)
    local lastErr
    for _, url in ipairs(urls) do
        local ok, res = pcall(game.HttpGet, game, url)
        if ok and type(res) == "string" and #res > 0 then
            return res
        end
        lastErr = res
    end
    error("gagal download prereq, semua URL dicoba gagal. Terakhir: " .. tostring(lastErr))
end

local function loadPrereq(relPath, globalName)
    local candidates = {
        -- relatif ke folder manifest (src/) -- TERBUKTI BISA
        "https://cdn.jsdelivr.net/gh/dawnpetal/loader@main/src/" .. relPath,
        -- relatif ke root repo (terbukti 404, disimpan sbg fallback)
        "https://cdn.jsdelivr.net/gh/dawnpetal/loader@main/" .. relPath,
        -- mirror GitHub raw, dua path yang sama
        "https://raw.githubusercontent.com/dawnpetal/loader/main/src/" .. relPath,
        "https://raw.githubusercontent.com/dawnpetal/loader/main/" .. relPath,
    }
    local src = fetchFirst(candidates)
    local fn = assert(loadstring(src), "gagal load " .. relPath)
    local ret = fn()
    if ret ~= nil then
        return ret
    end
    -- Fallback: file prereq mungkin menaruh modulnya di global/getgenv,
    -- bukan di return value.
    if type(getgenv) == "function" then
        local ok, g = pcall(getgenv)
        if ok and type(g) == "table" and g[globalName] ~= nil then
            return g[globalName]
        end
    end
    if _G[globalName] ~= nil then
        return _G[globalName]
    end
    error("Prereq " .. globalName .. " tidak mengembalikan modul")
end

local TaskManager = loadPrereq("utils/TaskManager.lua", "TaskManager")

-- ================= NEXRIFT WINDOW & HELPER =================

-- Dashboard, launcher (ikon), resize, dan skala dikelola lib Nexrift sendiri.
-- ToggleKey = default tombol buka/tutup di PC (bisa diganti dari Dashboard).
local Window = Nexrift:CreateWindow({
    Title = "Nexrift",
    AutoDashboard = true,
    ToggleKey = Enum.KeyCode.Q
})

local GROUP = "Nexrift"

local NOTIFY_COLORS = {
    Success = Color3.fromRGB(46, 204, 113),
    Error = Color3.fromRGB(235, 80, 70),
    Warning = Color3.fromRGB(241, 196, 15),
    Info = Color3.fromRGB(80, 160, 255)
}

-- Notify({Type, Title, Description, Duration}); Type "Default" = warna bawaan.
local function Notify(opts)
    opts = opts or {}
    Window.Notify(tostring(opts.Title or ""), tostring(opts.Description or ""), NOTIFY_COLORS[opts.Type],
        tonumber(opts.Duration))
end

local function newTab(title, subtitle, columns)
    return Window:Tab({
        Title = title,
        Subtitle = subtitle,
        Group = GROUP,
        Columns = columns or 1
    })
end

local function Acc(tab, title, open, column)
    return tab:Accordion({
        Title = title,
        Open = open,
        Column = column
    })
end

-- Langkah slider: bulat -> 1, ada pecahan -> 0.01 (Nexrift membulatkan 3 desimal).
local function autoStep(min, max, default)
    min = tonumber(min) or 0
    max = tonumber(max) or 100
    default = tonumber(default) or min
    if min % 1 ~= 0 or max % 1 ~= 0 or default % 1 ~= 0 then
        return 0.01
    end
    return 1
end

-- Ratakan fields paragraf ke list string. Bentuk yang dipakai game:
-- string, {Text = "...", IsSubField = true}, atau sub-tabel berisi bentuk-bentuk itu.
local function flattenFields(fields, out, indent)
    out = out or {}
    indent = indent or ""
    if type(fields) ~= "table" then
        if fields ~= nil then
            out[#out + 1] = indent .. tostring(fields)
        end
        return out
    end
    for _, f in ipairs(fields) do
        if type(f) == "table" then
            local txt = f.Text or f.text or f.Title or f.Name
            if txt ~= nil then
                local pre = (f.IsSubField or f.isSubField) and "  " or indent
                out[#out + 1] = pre .. tostring(txt)
            else
                flattenFields(f, out, indent .. "  ")
            end
        elseif f ~= nil then
            out[#out + 1] = indent .. tostring(f)
        end
    end
    return out
end

-- Paragraph dengan SetFields / ClearFields / SetTitle / GetFieldCount
-- (dipakai game untuk status yang sering di-update).
local function Paragraph(parent, title, fields)
    local lines = flattenFields(fields)
    local obj = parent:Paragraph({
        Title = title,
        Desc = table.concat(lines, "\n")
    })
    local count = #lines
    local para = {}
    function para:SetFields(newFields)
        local l = flattenFields(newFields)
        count = #l
        obj:SetDesc(table.concat(l, "\n"))
        return true
    end
    function para:ClearFields()
        count = 0
        obj:SetDesc("")
        return true
    end
    function para:SetTitle(t)
        obj:SetTitle(t)
        return true
    end
    function para:GetFieldCount()
        return count
    end
    return para
end

-- Opsi dropdown boleh string ("Teleport") atau tabel ({text = "Aetherite", guid = ...}).
-- Nexrift hanya menerima string: tampilkan string-nya, tapi callback tetap
-- menerima nilai aslinya (selection.text / selection.guid).
local function normOptions(options)
    local display, byDisplay, byValue = {}, {}, {}
    for _, opt in ipairs(options or {}) do
        local disp
        if type(opt) == "table" then
            disp = tostring(opt.text or opt.Text or opt.Name or opt.name or opt.Value or opt.value or opt[1] or "")
        else
            disp = tostring(opt)
        end
        display[#display + 1] = disp
        byDisplay[disp] = opt
        byValue[opt] = disp
    end
    return display, byDisplay, byValue
end

local function MappedDropdown(parent, cfg)
    local display, byDisplay, byValue = normOptions(cfg.Options)
    local multi = cfg.Multi == true
    local callback = cfg.Callback

    local function toGame(v)
        if multi then
            local out = {}
            for _, d in ipairs(v or {}) do
                out[#out + 1] = byDisplay[d] ~= nil and byDisplay[d] or d
            end
            return out
        end
        if v == nil then
            return nil
        end
        return byDisplay[v] ~= nil and byDisplay[v] or v
    end

    local api = parent:Dropdown({
        Title = cfg.Title,
        Desc = cfg.Desc,
        Options = display,
        Default = cfg.Default ~= nil and tostring(cfg.Default) or nil,
        Multi = multi,
        Flag = cfg.Flag,
        Callback = function(v)
            if callback then
                callback(toGame(v))
            end
        end
    })

    local dd = {}
    -- Dipakai game untuk menyegarkan daftar (waypoints, equipment, recipes).
    function dd:SetOptions(newOptions)
        display, byDisplay, byValue = normOptions(newOptions)
        api:Refresh(display)
        -- Buang pilihan yang sudah tidak ada di daftar baru.
        local cur = api:Get()
        if multi then
            local kept = {}
            for _, d in ipairs(cur or {}) do
                if byDisplay[d] ~= nil then
                    kept[#kept + 1] = d
                end
            end
            api:Set(kept, false)
        elseif cur ~= nil and byDisplay[cur] == nil then
            api:Set(nil, false)
        end
    end
    function dd:Set(v, fire)
        if multi then
            local mapped = {}
            for _, item in ipairs(v or {}) do
                mapped[#mapped + 1] = byValue[item] or tostring(item)
            end
            api:Set(mapped, fire)
        else
            api:Set(v ~= nil and (byValue[v] or tostring(v)) or nil, fire)
        end
    end
    function dd:Get()
        return toGame(api:Get())
    end
    return dd
end

