    -- ---------------------------------------------------------------- helpers
    local function create(class, props, parent)
        local inst = Instance.new(class)
        for k, v in pairs(props or {}) do
            inst[k] = v
        end
        if parent then
            inst.Parent = parent
        end
        return inst
    end

    local function corner(inst, r)
        return create("UICorner", {
            CornerRadius = UDim.new(0, r)
        }, inst)
    end

    local function stroke(inst, color, thickness, transparency)
        return create("UIStroke", {
            Color = color,
            Thickness = thickness or 1,
            Transparency = transparency or 0,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        }, inst)
    end

    local function gradient(inst, c0, c1, rot)
        return create("UIGradient", {
            Color = ColorSequence.new(c0, c1),
            Rotation = rot or 0
        }, inst)
    end

    local function padding(inst, l, t, r, b)
        return create("UIPadding", {
            PaddingLeft = UDim.new(0, l),
            PaddingTop = UDim.new(0, t),
            PaddingRight = UDim.new(0, r),
            PaddingBottom = UDim.new(0, b)
        }, inst)
    end

    local function label(parent, props)
        local d = {
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Font = Enum.Font.GothamMedium,
            TextSize = 13,
            TextColor3 = Theme.Text,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd
        }
        for k, v in pairs(props) do
            d[k] = v
        end
        return create("TextLabel", d, parent)
    end

    local function tween(inst, props, t, style, dir)
        local tw = TweenService:Create(inst, TweenInfo.new(t or 0.25, style or Enum.EasingStyle.Quint,
            dir or Enum.EasingDirection.Out), props)
        tw:Play()
        return tw
    end

    local function textWidth(text, size, font)
        local w = #tostring(text) * size * 0.6
        pcall(function()
            w = TextService:GetTextSize(tostring(text), size, font or Enum.Font.GothamBold, Vector2.new(1000, 100)).X
        end)
        return w
    end

    local NumberFormatter = {}
    NumberFormatter.Suffixes = {{1e21, "Sx"}, {1e18, "Qi"}, {1e15, "Qa"}, {1e12, "T"}, {1e9, "B"}, {1e6, "M"}, {1e3, "k"}}

    function NumberFormatter.Format(n)
        n = math.floor(n + 0.5)
        for _, data in ipairs(NumberFormatter.Suffixes) do
            if n >= data[1] then
                local value = math.floor((n / data[1]) * 100) / 100
                local str = tostring(value):gsub("%.0+$", ""):gsub("(%..-)0+$", "%1")
                return str .. data[2]
            end
        end
        return tostring(n)
    end

    local function formatBalance(n)
        n = math.floor((tonumber(n) or 0) + 0.5)
        if n >= 1e9 then
            return NumberFormatter.Format(n)
        end
        local s = tostring(n):reverse():gsub("(%d%d%d)", "%1,"):reverse()
        return (s:gsub("^,", ""))
    end

    -- ---------------------------------------------------------------- glyph (ikon gambar sendiri)
    local function newGlyph(parent, size)
        local frame = create("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.fromOffset(size, size)
        }, parent)
        local fills, strokes = {}, {}
        local g = {
            Frame = frame
        }
        function g.SetColor(col)
            for _, f in ipairs(fills) do
                f.BackgroundColor3 = col
            end
            for _, s in ipairs(strokes) do
                s.Color = col
            end
        end
        return g, fills, strokes
    end

    local function cartGlyph(parent, size, color)
        local g, fills, strokes = newGlyph(parent, size)
        local c = g.Frame
        local th = math.max(1.4, size * 0.09)
        local handle = create("Frame", {
            Position = UDim2.fromScale(0, 0.1),
            Size = UDim2.fromScale(0.22, 0.09),
            BackgroundColor3 = color,
            BorderSizePixel = 0
        }, c)
        corner(handle, 99)
        fills[#fills + 1] = handle
        local basket = create("Frame", {
            Position = UDim2.fromScale(0.2, 0.2),
            Size = UDim2.fromScale(0.78, 0.46),
            BackgroundTransparency = 1,
            BorderSizePixel = 0
        }, c)
        corner(basket, math.max(2, size * 0.1))
        strokes[#strokes + 1] = stroke(basket, color, th, 0)
        for _, x in ipairs({0.3, 0.72}) do
            local wheel = create("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(x, 0.84),
                Size = UDim2.fromScale(0.17, 0.17),
                BackgroundColor3 = color,
                BorderSizePixel = 0
            }, c)
            corner(wheel, 99)
            fills[#fills + 1] = wheel
        end
        return g
    end

    local function gridGlyph(parent, size, color)
        local g, _, strokes = newGlyph(parent, size)
        local th = math.max(1.2, size * 0.085)
        for i = 0, 3 do
            local q = create("Frame", {
                Position = UDim2.fromScale((i % 2) * 0.54 + 0.02, math.floor(i / 2) * 0.54 + 0.02),
                Size = UDim2.fromScale(0.42, 0.42),
                BackgroundTransparency = 1,
                BorderSizePixel = 0
            }, g.Frame)
            corner(q, 3)
            strokes[#strokes + 1] = stroke(q, color, th, 0)
        end
        return g
    end

    local function cardGlyph(parent, size, color)
        local g, fills, strokes = newGlyph(parent, size)
        local th = math.max(1.3, size * 0.09)
        local body = create("Frame", {
            Position = UDim2.fromScale(0.04, 0.16),
            Size = UDim2.fromScale(0.92, 0.68),
            BackgroundTransparency = 1,
            BorderSizePixel = 0
        }, g.Frame)
        corner(body, 3)
        strokes[#strokes + 1] = stroke(body, color, th, 0)
        local stripe = create("Frame", {
            Position = UDim2.fromScale(0.04, 0.34),
            Size = UDim2.fromScale(0.92, 0.14),
            BackgroundColor3 = color,
            BorderSizePixel = 0
        }, g.Frame)
        fills[#fills + 1] = stripe
        return g
    end

    local function gem(parent, size, order)
        local holder = create("Frame", {
            Name = "Gem",
            BackgroundTransparency = 1,
            Size = UDim2.fromOffset(size, size),
            LayoutOrder = order or 0
        }, parent)
        local d = create("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromOffset(size * 0.66, size * 0.66),
            Rotation = 45,
            BackgroundColor3 = Color3.new(1, 1, 1),
            BorderSizePixel = 0
        }, holder)
        corner(d, math.max(2, size * 0.14))
        gradient(d, Theme.AccentGlow, Theme.AccentDark, 90)
        stroke(d, Theme.AccentGlow, 1, 0.35)
        local hl = create("Frame", {
            Position = UDim2.fromScale(0.1, 0.1),
            Size = UDim2.fromScale(0.45, 0.45),
            BackgroundColor3 = Color3.new(1, 1, 1),
            BackgroundTransparency = 0.72,
            BorderSizePixel = 0
        }, d)
        corner(hl, 2)
        return holder
    end

    -- harga: gem untuk "$", "ƒ" untuk shard, teks biasa untuk mata uang lain
    local function renderPrice(parent, currency, amount, size, color)
        local f = create("Frame", {
            Name = "Price",
            BackgroundTransparency = 1,
            AutomaticSize = Enum.AutomaticSize.X,
            Size = UDim2.fromOffset(0, size + 6)
        }, parent)
        create("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder,
            Padding = UDim.new(0, 5)
        }, f)
        local text = NumberFormatter.Format(amount)
        if currency == "$" then
            gem(f, size + 2, 1)
        elseif currency == "ƒ" then
            label(f, {
                LayoutOrder = 1,
                Text = "ƒ",
                Font = Enum.Font.GothamBold,
                TextSize = size + 2,
                TextColor3 = Theme.AccentGlow,
                AutomaticSize = Enum.AutomaticSize.X,
                Size = UDim2.fromOffset(0, size + 6),
                TextTruncate = Enum.TextTruncate.None
            })
        else
            text = text .. " " .. tostring(currency)
        end
        label(f, {
            LayoutOrder = 2,
            Text = text,
            Font = Enum.Font.GothamBold,
            TextSize = size,
            TextColor3 = color or Theme.Text,
            AutomaticSize = Enum.AutomaticSize.X,
            Size = UDim2.fromOffset(0, size + 6),
            TextTruncate = Enum.TextTruncate.None
        })
        return f
    end

    local function currencyRank(c)
        if c == "$" then
            return 1
        elseif c == "ƒ" then
            return 2
        end
        return 3
    end

    -- ---------------------------------------------------------------- katalog (logic asli)
    local function categoryFolders()
        local items = ReplicatedStorage:FindFirstChild("Items")
        return {
            Pans = items and items:FindFirstChild("Pans"),
            Totems = items and items:FindFirstChild("Totems"),
            Potions = ReplicatedStorage:FindFirstChild("Potions"),
            Shovels = ReplicatedStorage:FindFirstChild("Shovels"),
            Sluices = items and items:FindFirstChild("Sluices")
        }
    end

    local function determineCategory(item)
        if not item then
            return "Others"
        end
        local lower = item.Name:lower()
        for category, folder in pairs(categoryFolders()) do
            for _, child in ipairs(folder:GetChildren()) do
                if child.Name:lower() == lower then
                    return category
                end
            end
        end
        return "Others"
    end

    local function buildCatalog()
        local catalog = {
            Pans = {},
            Shovels = {},
            Sluices = {},
            Potions = {},
            Totems = {},
            Others = {}
        }

        local purchRoot = Workspace:FindFirstChild("Purchasable")
        if not purchRoot then
            return catalog
        end

        for _, region in ipairs(purchRoot:GetChildren()) do
            if region:IsA("Folder") and #region:GetChildren() > 0 then
                for _, item in ipairs(region:GetChildren()) do
                    if item:IsA("Model") then
                        local shopItem = item:FindFirstChild("ShopItem")
                        local stats = shopItem and shopItem:FindFirstChild("Stats")
                        if shopItem and stats then
                            local isShardPrice = shopItem:GetAttribute("Price") == nil and
                                                     shopItem:GetAttribute("ShardPrice") ~= nil
                            local price = shopItem:GetAttribute(isShardPrice and "ShardPrice" or "Price")
                            local description = shopItem:GetAttribute("Description")

                            if price then
                                local category = determineCategory(item)
                                table.insert(catalog[category], {
                                    name = item.Name,
                                    description = description,
                                    price = price,
                                    currency = isShardPrice and "ƒ" or "$",
                                    category = category,
                                    model = item,
                                    shopItem = shopItem,
                                    iconImage = ICONS[category] or ICONS.Utility
                                })
                            else
                                for attrName, attrValue in pairs(shopItem:GetAttributes()) do
                                    if typeof(attrValue) == "number" and attrName ~= "Price" and attrName ~=
                                        "ShardPrice" then
                                        table.insert(catalog.Others, {
                                            name = item.Name,
                                            description = description,
                                            price = attrValue,
                                            currency = attrName,
                                            category = "Others",
                                            model = item,
                                            shopItem = shopItem,
                                            iconImage = ICONS.Utility
                                        })
                                        break
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end

        return catalog
    end

    local function getContainer()
        if gethui then
            local ok, result = pcall(gethui)
            if ok and result then
                return result
            end
        end
        return Player:WaitForChild("PlayerGui")
    end

    -- ---------------------------------------------------------------- class
    function NexriftShop.new(uiScale, opts)
        local self = setmetatable({}, NexriftShop)
        self.shoppingCart = {}
        self.selectedCategory = "All"
        self.uiScale = uiScale or 1
        self.opts = opts or {}
        self.buying = false
        self.visible = false
        self.token = 0
        self.chips = {}
        self.gui = nil
        self:CreateUI()
        return self
    end

    -- ----- cart (logic asli)
    function NexriftShop:AddToCart(itemData)
        for _, cartItem in ipairs(self.shoppingCart) do
            if cartItem.name == itemData.name then
                cartItem.quantity = cartItem.quantity + 1
                return
            end
        end

        table.insert(self.shoppingCart, {
            name = itemData.name,
            price = itemData.price,
            currency = itemData.currency,
            category = itemData.category,
            model = itemData.model,
            shopItem = itemData.shopItem,
            quantity = 1
        })
    end

    function NexriftShop:RemoveFromCart(itemName)
        for i, cartItem in ipairs(self.shoppingCart) do
            if cartItem.name == itemName then
                table.remove(self.shoppingCart, i)
                return
            end
        end
    end

    function NexriftShop:UpdateCartQuantity(itemName, delta)
        for i, cartItem in ipairs(self.shoppingCart) do
            if cartItem.name == itemName then
                cartItem.quantity = math.max(0, cartItem.quantity + delta)
                if cartItem.quantity == 0 then
                    table.remove(self.shoppingCart, i)
                end
                return
            end
        end
    end

    function NexriftShop:CalculateTotals()
        local totals = {}
        for _, cartItem in ipairs(self.shoppingCart) do
            totals[cartItem.currency] = (totals[cartItem.currency] or 0) + (cartItem.price * cartItem.quantity)
        end
        return totals
    end

    function NexriftShop:GetItemCount()
        local count = 0
        for _, cartItem in ipairs(self.shoppingCart) do
            count = count + cartItem.quantity
        end
        return count
    end

    function NexriftShop:ClearCart()
        self.shoppingCart = {}
    end

