            Font = Enum.Font.GothamBold,
            TextSize = 14,
            AutomaticSize = Enum.AutomaticSize.X,
            Size = UDim2.fromOffset(0, 34),
            TextTruncate = Enum.TextTruncate.None
        })
        self:SetupBalance()

        -- garis aksen di bawah header
        local line = create("Frame", {
            Position = UDim2.fromOffset(16, 70),
            Size = UDim2.new(1, -32, 0, 1),
            BackgroundColor3 = Theme.Accent,
            BorderSizePixel = 0,
            ZIndex = 3
        }, window)
        local lg = create("UIGradient", {
            Transparency = NumberSequence.new{NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0.25),
                                              NumberSequenceKeypoint.new(1, 1)},
            Offset = Vector2.new(-0.3, 0)
        }, line)
        TweenService:Create(lg, TweenInfo.new(3.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {
            Offset = Vector2.new(0.3, 0)
        }):Play()

        -- geser jendela lewat header
        local dragging, dragStart, startPos = false, nil, nil
        header.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType ==
                Enum.UserInputType.Touch then
                dragging = true
                dragStart = input.Position
                startPos = self.shell.Position
                local c
                c = input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        dragging = false
                        if c then
                            c:Disconnect()
                        end
                    end
                end)
            end
        end)
        local moveConn = UserInputService.InputChanged:Connect(function(input)
            if dragging and
                (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType ==
                    Enum.UserInputType.Touch) then
                local d = (input.Position - dragStart) / math.max(self.uiScale, 0.01)
                self.shell.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale,
                    startPos.Y.Offset + d.Y)
            end
        end)
        self.gui.Destroying:Connect(function()
            moveConn:Disconnect()
        end)
    end

    function NexriftShop:SetupBalance()
        local stat
        local ls = Player:FindFirstChild("leaderstats")
        if ls then
            for _, child in ipairs(ls:GetChildren()) do
                if (child:IsA("NumberValue") or child:IsA("IntValue")) and BALANCE_NAMES[child.Name:lower()] then
                    stat = child
                    break
                end
            end
        end
        self.balanceStat = stat
        if stat then
            stat.Changed:Connect(function()
                self:RefreshChip()
            end)
        end
        self:RefreshChip()
    end

    function NexriftShop:RefreshChip()
        if not self.chipText then
            return
        end
        if self.balanceStat then
            self.chipGem.Visible = true
            self.chipGrid.Frame.Visible = false
            self.chipText.Text = formatBalance(self.balanceStat.Value)
        else
            self.chipGem.Visible = false
            self.chipGrid.Frame.Visible = true
            local n = self.itemCount or 0
            self.chipText.Text = n .. (n == 1 and " item" or " items")
        end
    end

