            VerticalAlignment = Enum.VerticalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder,
            Padding = UDim.new(0, 8)
        }, bar)

        for i, name in ipairs(CATEGORIES) do
            local btn = create("TextButton", {
                Name = name,
                LayoutOrder = i,
                Size = UDim2.fromOffset(0, 34),
                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundColor3 = Theme.Chip,
                Text = "",
                AutoButtonColor = false,
                BorderSizePixel = 0
            }, bar)
            corner(btn, 17)
            local st = stroke(btn, Theme.Stroke, 1, 0.35)

            local chipFill = create("Frame", {
                Size = UDim2.fromScale(1, 1),
                BackgroundColor3 = Color3.new(1, 1, 1),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ZIndex = 1
            }, btn)
            corner(chipFill, 17)
            gradient(chipFill, Theme.Accent, Theme.AccentDark, 90)

            local row = create("Frame", {
                Size = UDim2.fromScale(0, 1),
                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundTransparency = 1,
                ZIndex = 2
            }, btn)
            padding(row, 14, 0, 16, 0)
            create("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                VerticalAlignment = Enum.VerticalAlignment.Center,
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 7)
            }, row)

            local setIcon
            if name == "All" then
                local g = gridGlyph(row, 16, Theme.TextDim)
                g.Frame.ZIndex = 2
                setIcon = g.SetColor
            else
                local img = create("ImageLabel", {
                    Size = UDim2.fromOffset(16, 16),
                    BackgroundTransparency = 1,
                    Image = ICONS[name] or ICONS.Utility,
                    ImageColor3 = Theme.TextDim,
                    ScaleType = Enum.ScaleType.Fit,
                    ZIndex = 2
                }, row)
                setIcon = function(col)
                    img.ImageColor3 = col
                end
            end
            local text = label(row, {
                LayoutOrder = 2,
                Text = name,
                Font = Enum.Font.GothamBold,
                TextSize = 13,
                TextColor3 = Theme.TextDim,
                AutomaticSize = Enum.AutomaticSize.X,
                Size = UDim2.fromOffset(0, 34),
                TextTruncate = Enum.TextTruncate.None,
                ZIndex = 2
            })

            self.chips[name] = {
                btn = btn,
                stroke = st,
                fill = chipFill,
                text = text,
                setIcon = setIcon,
                hover = false
            }

            btn.MouseEnter:Connect(function()
                local c = self.chips[name]
                c.hover = true
                if self.selectedCategory ~= name then
                    tween(c.stroke, {
                        Color = Theme.Accent,
                        Transparency = 0.1
                    }, 0.15)
                    tween(c.text, {
                        TextColor3 = Theme.Text
                    }, 0.15)
                    c.setIcon(Theme.Text)
                end
            end)
            btn.MouseLeave:Connect(function()
                local c = self.chips[name]
                c.hover = false
                if self.selectedCategory ~= name then
                    tween(c.stroke, {
                        Color = Theme.Stroke,
                        Transparency = 0.35
                    }, 0.2)
                    tween(c.text, {
                        TextColor3 = Theme.TextDim
                    }, 0.2)
                    c.setIcon(Theme.TextDim)
                end
            end)
            btn.MouseButton1Click:Connect(function()
                if self.selectedCategory == name then
                    return
                end
                self.selectedCategory = name
                self:RefreshChips(true)
                self:UpdateItemDisplay()
            end)
        end
    end

    function NexriftShop:RefreshChips(animate)
        local t = animate and 0.22 or 0
        for name, c in pairs(self.chips) do
            local on = (name == self.selectedCategory)
            tween(c.fill, {
                BackgroundTransparency = on and 0 or 1
            }, t)
            tween(c.stroke, {
                Color = on and Theme.AccentGlow or Theme.Stroke,
                Transparency = on and 0.2 or 0.35
            }, t)
            tween(c.text, {
                TextColor3 = on and Theme.Text or Theme.TextDim
            }, t)
            c.setIcon(on and Theme.Text or Theme.TextDim)
        end
    end

