        local hovering = false
        body.MouseEnter:Connect(function()
            tween(st, {
                Color = Theme.Accent,
                Transparency = 0.05
            }, 0.18)
            tween(body, {
                Position = UDim2.fromOffset(0, -2)
            }, 0.2)
            tween(glow1, {
                BackgroundTransparency = 0.8
            }, 0.25)
            tween(icon, {
                Size = UDim2.fromOffset(52, 52)
            }, 0.25, Enum.EasingStyle.Back)
        end)
        body.MouseLeave:Connect(function()
            tween(st, {
                Color = Theme.Stroke,
                Transparency = 0.3
            }, 0.22)
            tween(body, {
                Position = UDim2.fromOffset(0, 0)
            }, 0.22)
            tween(glow1, {
                BackgroundTransparency = 0.9
            }, 0.25)
            tween(icon, {
                Size = UDim2.fromOffset(46, 46)
            }, 0.25)
        end)
        local flashToken = 0
        btn.MouseEnter:Connect(function()
            hovering = true
            tween(bfill, {
                BackgroundTransparency = 0.45
            }, 0.15)
        end)
        btn.MouseLeave:Connect(function()
            hovering = false
            if flashToken == 0 or btext.Text == "Add to Cart" then
                tween(bfill, {
                    BackgroundTransparency = 1
                }, 0.2)
            end
        end)
        btn.MouseButton1Click:Connect(function()
            self:AddToCart(itemData)
            self:UpdateCart(itemData.name)

            flashToken = flashToken + 1
            local my = flashToken
            btext.Text = "✓ Added"
            tween(bfill, {
                BackgroundTransparency = 0
            }, 0.12)
            task.delay(1, function()
                if my == flashToken and btext.Parent then
                    btext.Text = "Add to Cart"
                    tween(bfill, {
                        BackgroundTransparency = hovering and 0.45 or 1
                    }, 0.25)
                end
            end)
        end)

        return cell, body
    end

    function NexriftShop:UpdateItemDisplay()
        if not self.gui then
            return
        end

        for _, child in ipairs(self.itemsScroll:GetChildren()) do
            if child:IsA("Frame") then
                child:Destroy()
            end
        end
        self.itemsScroll.CanvasPosition = Vector2.new(0, 0)

        local catalog = buildCatalog()
        local list = {}
        for category, items in pairs(catalog) do
            if self.selectedCategory == "All" or self.selectedCategory == category then
                for _, itemData in ipairs(items) do
                    list[#list + 1] = itemData
                end
            end
        end
        table.sort(list, function(a, b)
            return ("Item_" .. a.name) < ("Item_" .. b.name)
        end)

        for i, itemData in ipairs(list) do
            local ok, _, body = pcall(self.CreateItemCard, self, itemData, i)
            if ok and body then
                task.delay(math.min(i - 1, 12) * 0.035, function()
                    if body.Parent then
                        tween(body, {
                            Position = UDim2.fromOffset(0, 0)
                        }, 0.45, Enum.EasingStyle.Back)
                    end
                end)
            end
        end

        self.itemCount = #list
        self.itemsEmpty.Visible = (#list == 0)
        self:RefreshChip()
    end

