            Size = UDim2.fromScale(1, 1),
            Position = animate and UDim2.fromOffset(28, 0) or UDim2.fromOffset(0, 0),
            BackgroundColor3 = Theme.CardAlt,
            BackgroundTransparency = 0.35,
            BorderSizePixel = 0
        }, holder)
        corner(rowBody, 11)
        stroke(rowBody, Theme.Stroke, 1, 0.45)
        if animate then
            tween(rowBody, {
                Position = UDim2.fromOffset(0, 0)
            }, 0.45, Enum.EasingStyle.Back)
        end

        label(rowBody, {
            Text = cartItem.name,
            Position = UDim2.fromOffset(12, 8),
            Size = UDim2.new(1, -44, 0, 18),
            Font = Enum.Font.GothamBold,
            TextSize = 13
        })

        local remove = create("TextButton", {
            AnchorPoint = Vector2.new(1, 0),
            Position = UDim2.new(1, -8, 0, 7),
            Size = UDim2.fromOffset(22, 22),
            BackgroundTransparency = 1,
            Text = "✕",
            TextColor3 = Theme.TextDim,
            TextSize = 12,
            Font = Enum.Font.GothamBold,
            AutoButtonColor = false,
            BorderSizePixel = 0
        }, rowBody)
        remove.MouseEnter:Connect(function()
            tween(remove, {
                TextColor3 = Theme.Danger
            }, 0.12)
        end)
        remove.MouseLeave:Connect(function()
            tween(remove, {
                TextColor3 = Theme.TextDim
            }, 0.15)
        end)
        remove.MouseButton1Click:Connect(function()
            self:RemoveFromCart(cartItem.name)
            self:UpdateCart()
        end)

        local priceRow = create("Frame", {
            AnchorPoint = Vector2.new(0, 1),
            Position = UDim2.new(0, 12, 1, -9),
            Size = UDim2.new(0.5, -12, 0, 22),
            BackgroundTransparency = 1
        }, rowBody)
        local p = renderPrice(priceRow, cartItem.currency, cartItem.price * cartItem.quantity, 14, Theme.Text)
        p.AnchorPoint = Vector2.new(0, 0.5)
        p.Position = UDim2.fromScale(0, 0.5)

        local qty = create("Frame", {
            AnchorPoint = Vector2.new(1, 1),
            Position = UDim2.new(1, -9, 1, -8),
            Size = UDim2.fromOffset(78, 24),
            BackgroundColor3 = Color3.fromRGB(20, 9, 12),
            BorderSizePixel = 0
        }, rowBody)
        corner(qty, 8)
        stroke(qty, Theme.Stroke, 1, 0.4)

        local function stepper(text, x, delta)
            local b = create("TextButton", {
                Position = UDim2.fromOffset(x, 0),
                Size = UDim2.fromOffset(24, 24),
                BackgroundTransparency = 1,
                Text = text,
                TextColor3 = Theme.Text,
                TextSize = 16,
                Font = Enum.Font.GothamBold,
                AutoButtonColor = false,
                BorderSizePixel = 0
            }, qty)
            b.MouseEnter:Connect(function()
                tween(b, {
                    TextColor3 = Theme.AccentGlow
                }, 0.12)
            end)
            b.MouseLeave:Connect(function()
                tween(b, {
                    TextColor3 = Theme.Text
                }, 0.15)
            end)
            b.MouseButton1Click:Connect(function()
                self:UpdateCartQuantity(cartItem.name, delta)
                self:UpdateCart()
            end)
        end
        stepper("−", 0, -1)
        label(qty, {
            Text = tostring(cartItem.quantity),
            Position = UDim2.fromOffset(24, 0),
            Size = UDim2.fromOffset(30, 24),
            TextXAlignment = Enum.TextXAlignment.Center,
            Font = Enum.Font.GothamBold,
            TextSize = 13,
            TextTruncate = Enum.TextTruncate.None
        })
        stepper("+", 54, 1)

        return holder
    end

    function NexriftShop:UpdateCart(addedName)
        if not self.gui then
            return
        end

        for _, child in ipairs(self.cartScroll:GetChildren()) do
            if child:IsA("Frame") then
                child:Destroy()
            end
        end

        for i, cartItem in ipairs(self.shoppingCart) do
            local holder = self:CreateCartItem(cartItem, addedName ~= nil and cartItem.name == addedName)
            holder.LayoutOrder = i
        end

        local count = self:GetItemCount()
        self.cartEmpty.Visible = (#self.shoppingCart == 0)
        self.cartScroll.Visible = (#self.shoppingCart > 0)

        local pillText = count .. (count == 1 and " item" or " items")
        self.cartPill.Text = pillText
        self.cartPillFrame.Size = UDim2.fromOffset(math.max(54, textWidth(pillText, 11) + 22), 22)
        if addedName then
            self.cartPillScale.Scale = 1.18
            tween(self.cartPillScale, {
                Scale = 1
            }, 0.4, Enum.EasingStyle.Back)
        end

        -- total (per mata uang, urut: $ lalu ƒ lalu lainnya)
        for _, child in ipairs(self.totalHolder:GetChildren()) do
            if not child:IsA("UIListLayout") then
                child:Destroy()
            end
        end
        local totals = self:CalculateTotals()
        local currencies = {}
        for currency in pairs(totals) do
            currencies[#currencies + 1] = currency
        end
        table.sort(currencies, function(a, b)
            local ra, rb = currencyRank(a), currencyRank(b)
            if ra ~= rb then
                return ra < rb
            end
            return tostring(a) < tostring(b)
        end)
        if #currencies == 0 then
            local z = renderPrice(self.totalHolder, "$", 0, 17, Theme.Text)
            z.LayoutOrder = 1
        else
            for i, currency in ipairs(currencies) do
                if i > 1 then
                    label(self.totalHolder, {
                        LayoutOrder = i * 2 - 2,
                        Text = "+",
                        Font = Enum.Font.GothamBold,
                        TextSize = 14,
                        TextColor3 = Theme.TextDim,
                        Size = UDim2.fromOffset(10, 28),
                        TextXAlignment = Enum.TextXAlignment.Center,
                        TextTruncate = Enum.TextTruncate.None
                    })
                end
                local p = renderPrice(self.totalHolder, currency, totals[currency], 17, Theme.Text)
                p.LayoutOrder = i * 2 - 1
            end
        end

        self:SetCheckoutState(self.buying and "processing" or ((#self.shoppingCart > 0) and "idle" or "empty"))
    end

    function NexriftShop:SetCheckoutState(state)
        local c = self.checkout
        if not c then
            return
        end
        if state == "idle" then
            c.text.Text = "Checkout"
            tween(c.fill, {
                BackgroundTransparency = 0
            }, 0.2)
            tween(c.ok, {
                BackgroundTransparency = 1
            }, 0.2)
            tween(c.text, {
                TextColor3 = Theme.Text
            }, 0.2)
        elseif state == "empty" then
            c.text.Text = "Checkout"
            tween(c.fill, {
                BackgroundTransparency = 0.7
            }, 0.2)
            tween(c.ok, {
                BackgroundTransparency = 1
            }, 0.2)
            tween(c.text, {
                TextColor3 = Theme.TextDim
            }, 0.2)
        elseif state == "processing" then
            c.text.Text = "Processing..."
            tween(c.fill, {
                BackgroundTransparency = 0.45
            }, 0.15)
            tween(c.ok, {
                BackgroundTransparency = 1
            }, 0.15)
        elseif state == "done" then
            c.text.Text = "Completed"
            tween(c.ok, {
                BackgroundTransparency = 0
            }, 0.2)
        end
    end

    function NexriftShop:ProcessCheckout()
        if self.buying or #self.shoppingCart == 0 then
            return
        end

        self.buying = true
        self:SetCheckoutState("processing")

        local sent = 0
        local snapshot = {}
        for i, cartItem in ipairs(self.shoppingCart) do
            snapshot[i] = cartItem
        end

        local shopRemotes = ReplicatedStorage:FindFirstChild("Remotes")
        shopRemotes = shopRemotes and shopRemotes:FindFirstChild("Shop")
        local remote = shopRemotes and shopRemotes:FindFirstChild("BuyItem")

        for _, cartItem in ipairs(snapshot) do
            for _ = 1, cartItem.quantity do
                if cartItem.shopItem and remote then
                    pcall(function()
                        remote:InvokeServer(cartItem.shopItem)
                    end)
                    sent = sent + 1
                    task.wait(0.1)
                end
            end
        end

        self:ClearCart()
        self.buying = false
        self:UpdateCart()
        self:SetCheckoutState("done")

        if self.opts.Notify then
            pcall(self.opts.Notify, {
                Type = "Success",
                Title = "Checkout complete",
                Description = "Sent " .. sent .. " purchase request" .. (sent == 1 and "" or "s") .. " to the shop.",
                Duration = 4
            })
        end

        task.wait(1.5)
        if not self.buying then
            self:SetCheckoutState((#self.shoppingCart > 0) and "idle" or "empty")
        end
    end

    -- ----- buka / tutup (animasi)
    function NexriftShop:Show()
        if not self.gui or self.visible then
            return
        end
        self.visible = true
        self.token = self.token + 1

        self.gui.Enabled = true
        self.window.GroupTransparency = 1
        self.scaleObj.Scale = self.uiScale * 0.9
        self.glow.ImageTransparency = 1

        self:UpdateItemDisplay()

        tween(self.window, {
            GroupTransparency = 0
        }, 0.25)
        tween(self.scaleObj, {
            Scale = self.uiScale
        }, 0.5, Enum.EasingStyle.Back)
        tween(self.glow, {
            ImageTransparency = 0.7
        }, 0.5)
    end

    function NexriftShop:Hide()
        if not self.gui or not self.visible then
            return
        end
        self.visible = false
        self.token = self.token + 1
        local my = self.token

        tween(self.window, {
            GroupTransparency = 1
        }, 0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
        tween(self.scaleObj, {
            Scale = self.uiScale * 0.94
        }, 0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
        tween(self.glow, {
            ImageTransparency = 1
        }, 0.2)
        task.delay(0.22, function()
            if self.token == my and self.gui then
                self.gui.Enabled = false
            end
        end)
    end

    function NexriftShop:Toggle()
        if self.visible then
            self:Hide()
        else
            self:Show()
        end
    end
end

