    local tab = newTab("Tools", "Equipment reforging and tool enchantment", 2)

    local ReforgeSection = Acc(tab, "Equipment Reforging", true, 1)

    local selectedGUID = nil
    local equipmentInfo = Paragraph(ReforgeSection, "Equipment Details", {})

    local equipmentReforgeDropdown = MappedDropdown(ReforgeSection, {
        Title = "Choose Equipment",
        Options = {},
        Flag = "prospecting.reforge.equipment",
        Callback = function(selection)
            if type(selection) ~= "table" then
                selectedGUID = nil
                ReforgeModule.updateInfo(nil, equipmentInfo)
                return
            end
            selectedGUID = selection.guid
            ReforgeModule.updateInfo(selectedGUID, equipmentInfo)
        end
    })

    ReforgeSection:Button({
        Title = "Load Inventory Equipment",
        Callback = function()
            local equipmentOptions = {}
            local nameCounts = {}

            if BackpackTwo and BackpackTwo.GetChildren then
                for _, child in ipairs(BackpackTwo:GetChildren() or {}) do
                    if child and child.GetAttribute and child:GetAttribute("ItemType") == "Equipment" then
                        local baseName = tostring(child.Name or "Unknown")
