local function initializeCraftingTab()
    local tab = newTab("Crafting", "Equipment crafting and resource conversion", 2)

    local CraftingSection = Acc(tab, "Equipment Crafting", true, 1)

    local craftingStatus = Paragraph(CraftingSection, "Crafting Status",
        {"No equipment selected", "Select an equipment to begin"})

    local function tick()
        local eq = State.Crafting.selectedEquipment
        if not eq then
            craftingStatus:SetFields({"No equipment selected", "Select an equipment to begin"})
            return
        end

        if State.Crafting.selectBestOres then
            State.Crafting.selectedMaterials = CraftingModule.selectBest(eq.Data)
        end

        local fields = CraftingModule.buildFields(eq, State.Crafting.selectedMaterials)
        craftingStatus:SetFields(fields)
    end

    local equipmentDropdown = MappedDropdown(CraftingSection, {
        Title = "Select Equipment",
        Options = {},
        Flag = "prospecting.crafting.equipment",
        Callback = function(selection)
            for _, recipe in ipairs(State.Crafting.discoveredRecipes) do
                if recipe.Name == selection then
                    State.Crafting.selectedEquipment = recipe
                    State.Crafting.selectedMaterials = {}
                    tick()
                    return
                end
            end
        end
    })

    CraftingSection:Button({
        Title = "Load Discovered Recipes",
        Callback = function()
            State.Crafting.discoveredRecipes = CraftingModule.getDiscoveredRecipes()
            local options = {}
            for i = 1, #State.Crafting.discoveredRecipes do
                options[#options + 1] = State.Crafting.discoveredRecipes[i].Name
            end
            equipmentDropdown:SetOptions(options)
            Utility.createNotification("Loaded " .. #options .. " recipes", 3)
        end
    })

    CraftingSection:Toggle({
        Title = "Auto Select Best Materials",
        Desc = "Automatically select highest quality materials when equipment is chosen",
        Default = false,
        Flag = "prospecting.crafting.best_materials",
        Callback = function(state)
            State.Crafting.selectBestOres = state
            tick()
        end
    })

    CraftingSection:Button({
        Title = "Craft Equipment",
        Callback = function()
            local eq = State.Crafting.selectedEquipment
            if not eq then
                Utility.createNotification("No equipment selected", 3)
                return
            end
            if State.Crafting.selectBestOres then
                State.Crafting.selectedMaterials = CraftingModule.selectBest(eq.Data)
            end
            if not CraftingModule.canCraft(eq.Data, State.Crafting.selectedMaterials) then
                Utility.createNotification("Missing materials", 3)
                return
            end
            local success, result = CraftingModule.craft(eq.Item, State.Crafting.selectedMaterials)
            State.Crafting.selectedMaterials = {}
            task.wait(0.5)
            tick()
            if success then
                Utility.createNotification("Crafted " .. eq.Name .. "!", 3)
            else
                Utility.createNotification("Failed: " .. tostring(result), 3)
            end
        end
    })

    CraftingSection:Toggle({
        Title = "Enable Automatic Crafting",
        Desc = "Continuously craft selected equipment when materials are available",
        Default = false,
        Flag = "prospecting.crafting.autocraft",
        Callback = function(state)
            State.Crafting.autocraft = state
            if not state or State.Crafting.autocraftRunning then
                return
            end
            State.Crafting.autocraftRunning = true

            task.spawn(function()
                while State.Crafting.autocraft do
                    local eq = State.Crafting.selectedEquipment
                    if not eq then
                        task.wait(1)
                    else
                        if State.Crafting.selectBestOres then
                            State.Crafting.selectedMaterials = CraftingModule.selectBest(eq.Data)
                        end

                        tick()

                        if CraftingModule.canCraft(eq.Data, State.Crafting.selectedMaterials) then
                            local success, result = CraftingModule.craft(eq.Item, State.Crafting.selectedMaterials)
                            State.Crafting.selectedMaterials = {}
                            task.wait(0.5)
                            tick()
                            if success then
                                task.wait(0.5)
                            else
                                Utility.createNotification("Autocraft failed: " .. tostring(result), 3)
                                task.wait(3)
                            end
                        else
                            task.wait(2)
                        end
                    end
                end
                State.Crafting.autocraftRunning = false
            end)
        end
    })

    local FireflySection = Acc(tab, "Firefly Flare Conversion", true, 2)

    local fireflyAmount = 1
    local FireflyCrafting = false

    FireflySection:Textbox({
        Title = "Conversion Amount",
        Desc = "One Firefly Stone produces one Firefly Flare.",
        Default = "1",
        Flag = "prospecting.crafting.firefly_amount",
        Callback = function(input)
            local value = tonumber(input)
            if not value or value ~= math.floor(value) or value < 1 or value >= 1000 then
                Notify({
                    Type = "Error",
                    Title = "Invalid Amount",
                    Description = "Enter a whole number between 1 and 999."
                })
                return
            end
            fireflyAmount = value
        end
    })

    FireflySection:Button({
        Title = "Begin Conversion",
        Desc = "Convert Firefly Stones to Firefly Flares at the conversion table.",
        Callback = function()
            if FireflyCrafting then
                Notify({
                    Type = "Warning",
                    Title = "Already Converting",
                    Description = "Conversion already in progress."
                })
                return
            end
            FireflyCrafting = true
            task.spawn(function()
                FireflyModule.craft(fireflyAmount)
                FireflyCrafting = false
            end)
        end
    })

    FireflySection:Button({
        Title = "Stop Conversion",
        Callback = function()
            if not FireflyCrafting then
                Notify({
                    Type = "Info",
                    Title = "Idle",
                    Description = "No conversion running."
                })
                return
            end
            FireflyModule.stop()
            Notify({
                Type = "Warning",
                Title = "Stopping",
                Description = "Halting conversion."
            })
        end
    })

    Paragraph(FireflySection, "Conversion Requirements",
        {"You must be near the firefly conversion table to begin."})
end

local function initializeFavouriteTab()
    local tab = newTab("Favourite", "Favourite valuable items", 2)

    local PreservationSection = Acc(tab, "Item Preservation System", true, 1)

    local selectedModifiers = {}
    local selectedOres = {} -- MULTI-SELECT: bisa pilih banyak ore sekaligus
    local autoFavEnabled = false

    MappedDropdown(PreservationSection, {
        Title = "Select Modifier(s)",
        Options = CraftingModule.getModifierNames(),
        Multi = true,
        Flag = "prospecting.favourite.modifiers",
        Callback = function(values)
            selectedModifiers = {}
            for _, v in pairs(values or {}) do
                table.insert(selectedModifiers, v)
            end
        end
    })

    PreservationSection:Button({
        Title = "Preserve Items By Modifier",
        Callback = function()
            if #selectedModifiers == 0 then
                Notify({
                    Type = "Warning",
                    Title = "No Modifiers Selected",
                    Description = "Select at least one modifier first."
                })
                return
            end

            for _, item in pairs(BackpackTwo:GetChildren()) do
                for _, modifier in ipairs(selectedModifiers) do
                    if FavouriteModule.isValuable(item) and FavouriteModule.matchesModifier(item, modifier) then
                        FavouriteModule.favourite(item)
                        break
                    end
                end
            end

            Notify({
                Type = "Success",
                Title = "Complete",
                Description = "Items with selected modifiers have been preserved."
            })
        end
    })

    MappedDropdown(PreservationSection, {
        Title = "Select Ore Type",
        Desc = "Multi-select: bisa pilih banyak ore sekaligus.",
        Options = CraftingModule.getOreNames(),
        Multi = true,
        Flag = "prospecting.favourite.ore",
        Callback = function(value)
            selectedOres = {}
            if type(value) == "table" then
                for _, v in pairs(value) do
                    table.insert(selectedOres, v)
                end
            elseif value ~= nil then
                table.insert(selectedOres, value)
            end
        end
    })

    PreservationSection:Button({
        Title = "Preserve Items By Ore",
        Callback = function()
            if #selectedOres == 0 then
                Notify({
                    Type = "Warning",
                    Title = "No Ore Selected",
                    Description = "Select at least one ore type first."
                })
                return
            end

            for _, item in pairs(BackpackTwo:GetChildren()) do
                if FavouriteModule.isValuable(item) and FavouriteModule.matchesAnyOre(item, selectedOres) then
                    FavouriteModule.favourite(item)
                end
            end

            Notify({
                Type = "Success",
                Title = "Complete",
                Description = "All matching ore items have been preserved."
            })
        end
    })

    PreservationSection:Button({
        Title = "Preserve Ore with Modifiers",
        Callback = function()
            if #selectedOres == 0 or #selectedModifiers == 0 then
                Notify({
                    Type = "Warning",
                    Title = "Selection Incomplete",
                    Description = "Select at least one ore type and at least one modifier."
                })
                return
            end

            for _, item in pairs(BackpackTwo:GetChildren()) do
                if FavouriteModule.isValuable(item) and FavouriteModule.matchesAnyOre(item, selectedOres) then
                    for _, modifier in ipairs(selectedModifiers) do
                        if FavouriteModule.matchesModifier(item, modifier) then
                            FavouriteModule.favourite(item)
                            break
                        end
                    end
                end
            end

            Notify({
                Type = "Success",
                Title = "Complete",
                Description = "Matching items have been preserved."
            })
        end
    })

    PreservationSection:Toggle({
        Title = "Enable Automatic Preservation",
        Desc = "Automatically preserve items as they are obtained.",
        Default = false,
        Flag = "prospecting.favourite.auto",
        Callback = function(state)
            autoFavEnabled = state
        end
    })

    BackpackTwo.ChildAdded:Connect(function(item)
        if not autoFavEnabled then
            return
        end
        if not FavouriteModule.isValuable(item) then
            return
        end

        if #selectedOres > 0 and #selectedModifiers > 0 then
            -- Dua-duanya dipilih = harus kena ore (salah satu) DAN modifier (salah satu)
            if FavouriteModule.matchesAnyOre(item, selectedOres) then
                for _, modifier in ipairs(selectedModifiers) do
                    if FavouriteModule.matchesModifier(item, modifier) then
                        task.wait(0.1)
                        FavouriteModule.favourite(item)
                        break
                    end
                end
            end
        elseif #selectedOres > 0 then
            if FavouriteModule.matchesAnyOre(item, selectedOres) then
                task.wait(0.1)
                FavouriteModule.favourite(item)
            end
        elseif #selectedModifiers > 0 then
            for _, modifier in ipairs(selectedModifiers) do
                if FavouriteModule.matchesModifier(item, modifier) then
                    task.wait(0.1)
                    FavouriteModule.favourite(item)
                    break
                end
            end
        end
    end)

    local GuideSection = Acc(tab, "Guide", true, 2)
    Paragraph(GuideSection, "Preservation Guide", {
        "Select Modifier: Choose which modifiers to protect.",
        "Preserve Items By Modifier: Protects all items with selected modifiers.",
        "Select Ore Type: Multi-select, bisa pilih banyak ore sekaligus.",
        "Preserve Items By Ore: Protects all items of the selected ores.",
        "Preserve Ore with Modifiers: Requires both ore and modifier selections.",
        "Enable Automatic Preservation: Protects newly obtained items based on your selections."
    })
end

local function initializeShopTab()
    local tab = newTab("Shop", "Amazong - Credits: Jeff Bozo", 1)

    local MarketplaceSection = Acc(tab, "Marketplace", true)

    Paragraph(MarketplaceSection, "Amazong Marketplace", {"Browse and purchase items from the amazong marketplace."})

    MarketplaceSection:Button({
        Title = "Open Marketplace",
        Desc = "Open or close the Nexrift shop window",
        Callback = function()
            amazong:Toggle()
        end
    })
end

local function initializeMiscellaneousTab()
    local tab = newTab("Miscellaneous", "Excavation sites, environmental barriers, and utilities", 2)

    local ExcavationSection = Acc(tab, "Archaeological Sites", true, 1)

    local excavationStatus = Paragraph(ExcavationSection, "Site Status",
        {"Idle", "No site selected"})

    MappedDropdown(ExcavationSection, {
        Title = "Select Excavation Site",
        Options = ExcavationModule.getNames(),
        Flag = "prospecting.excavation.selected_site",
        Callback = function(s)
            State.Excavation.selected = s
            excavationStatus:SetFields({"Status: Ready", "Selected: " .. tostring(s)})
        end
    })

    ExcavationSection:Button({
        Title = "Begin Excavation",
        Callback = function()
            if not State.Excavation.selected then
                excavationStatus:SetFields({"Status: Error", "No site selected"})
                return
            end

            local ok, msg = ExcavationModule.start()
            if ok then
                excavationStatus:SetFields({"Status: Running", "Site: " .. State.Excavation.selected})
            else
                excavationStatus:SetFields({"Status: Failed", tostring(msg)})
            end
        end
    })

    ExcavationSection:Toggle({
        Title = "Auto Claim Rewards",
        Default = true,
        Flag = "prospecting.excavation.auto_claim",
        Callback = function(state)
            State.Excavation.autoClaim = state
            excavationStatus:SetFields({"Status: " .. (state and "Auto-Claim Enabled" or "Auto-Claim Disabled"),
                                        "Site: " .. tostring(State.Excavation.selected)})

            if not state then
                return
            end

            task.spawn(function()
                while State.Excavation.autoClaim do
                    if ExcavationModule.getCurrentStatus() == "Finished" then
                        ExcavationModule.claim()
                    end
                    task.wait(1)
                end
            end)
        end
    })

    ExcavationSection:Toggle({
        Title = "Auto Start Excavation",
        Default = false,
        Flag = "prospecting.excavation.auto_start",
        Callback = function(state)
            State.Excavation.autoStart = state

            if not state then
                excavationStatus:SetFields({"Status: Auto-Start Disabled", "Site: " .. tostring(State.Excavation.selected)})
                return
            end

            if State.Excavation.autoStartRunning then
                excavationStatus:SetFields({"Status: Auto-Start Running", "Site: " .. tostring(State.Excavation.selected)})
                return
            end

            State.Excavation.autoStartRunning = true
            excavationStatus:SetFields({"Status: Auto-Start Enabled", "Site: " .. tostring(State.Excavation.selected)})

            task.spawn(function()
                while State.Excavation.autoStart do
                    if not State.Excavation.selected then
                        excavationStatus:SetFields({"Status: Waiting", "Select an excavation site to auto-start"})
                        task.wait(2)
                        continue
                    end

                    local ok, msg = ExcavationModule.autoStartCycle()
                    if ok then
                        excavationStatus:SetFields({"Status: Running", "Site: " .. tostring(State.Excavation.selected)})
                    elseif msg ~= "Excavation already active." then
                        excavationStatus:SetFields({"Status: Waiting", tostring(msg)})
                    end

                    task.wait(5)
                end

                State.Excavation.autoStartRunning = false
            end)
        end
    })

    local PlayerSettingsSection = Acc(tab, "Character Settings", false, 1)

    PlayerSettingsSection:Section("Humanoid Properties")

    local jumpPower = (Humanoid and Humanoid.JumpPower) or 50
    local walkSpeedValue = Humanoid and Humanoid.WalkSpeed or 16

    local function applySavedHumanoidSettings()
        if not Humanoid then
            return
        end

        Humanoid.WalkSpeed = walkSpeedValue
        Humanoid.UseJumpPower = true
        Humanoid.JumpPower = jumpPower
    end

    PlayerSettingsSection:Slider({
        Title = "Movement Speed",
        Min = 0,
        Max = 100,
        Default = walkSpeedValue,
        Step = autoStep(0, 100, walkSpeedValue),
        Flag = "prospecting.character.walk_speed",
        Callback = function(val)
            pcall(function()
                walkSpeedValue = val
                applySavedHumanoidSettings()
            end)
        end
    })

    if Humanoid then
        Humanoid:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
            if Humanoid.WalkSpeed ~= walkSpeedValue then
                Humanoid.WalkSpeed = walkSpeedValue
            end
        end)
    end

    PlayerSettingsSection:Slider({
        Title = "Jump Height",
        Min = 1,
        Max = 100,
        Default = jumpPower,
        Step = autoStep(1, 100, jumpPower),
        Flag = "prospecting.character.jump_power",
        Callback = function(val)
            pcall(function()
                jumpPower = val
                applySavedHumanoidSettings()
            end)
        end
    })

    if Humanoid then
        Humanoid:GetPropertyChangedSignal("JumpPower"):Connect(function()
            if Humanoid.JumpPower ~= jumpPower then
                Humanoid.UseJumpPower = true
                Humanoid.JumpPower = jumpPower
            end
        end)
    end

    Player.CharacterAdded:Connect(function()
        task.wait(1)
        applySavedHumanoidSettings()
    end)

    PlayerSettingsSection:Section("Camera and Environment")

    PlayerSettingsSection:Slider({
        Title = "Camera Field of View",
        Min = 30,
        Max = 120,
        Default = Camera.FieldOfView,
        Step = 1,
        Flag = "prospecting.character.camera_fov",
        Callback = function(value)
            Camera.FieldOfView = value
        end
    })

    local fogDensity = 0.1
    local atmosphere = Services.Lighting:FindFirstChildWhichIsA("Atmosphere") or
                           Instance.new("Atmosphere", Services.Lighting)

    Services.RunService.RenderStepped:Connect(function()
        if atmosphere then
            atmosphere.Density = math.clamp(fogDensity, 0, 1)
        end
    end)

    PlayerSettingsSection:Slider({
        Title = "Environmental Fog Density",
        Min = 0.30,
        Max = 1,
        Default = 0.40,
        Step = 0.01,
        Flag = "prospecting.character.fog_density",
        Callback = function(value)
            fogDensity = value
        end
    })

    local RemoveBarriersSection = Acc(tab, "Environmental Barriers", false, 2)

    RemoveBarriersSection:Toggle({
        Title = "Disable Vine Blockades",
        Desc = "Temporarily disables vine collision without deleting the objects.",
        Default = false,
        Flag = "prospecting.barriers.vines",
        Callback = function(state)
            State.Barriers.vines = state
            if not BarrierRemovalModule.toggleVines(state) then
                Utility.createNotification("Vine blockades were not found.", 4)
            end
        end
    })

    RemoveBarriersSection:Toggle({
        Title = "Disable Abyssal Gate",
        Desc = "Temporarily disables the Abyssal Gate collision and can restore it.",
        Default = false,
        Flag = "prospecting.barriers.abyssal_gate",
        Callback = function(state)
            State.Barriers.abyssalGate = state
            if not BarrierRemovalModule.toggleAbyssalGate(state) then
                Utility.createNotification("Abyssal Gate was not found.", 4)
            end
        end
    })

    RemoveBarriersSection:Toggle({
        Title = "Disable Peak Obstruction",
        Desc = "Temporarily disables the summit blockage and can restore it.",
        Default = false,
        Flag = "prospecting.barriers.peak_obstruction",
        Callback = function(state)
            State.Barriers.peakObstruction = state
            if not BarrierRemovalModule.toggleMountainBlock(state) then
                Utility.createNotification("Peak obstruction was not found.", 4)
            end
        end
    })

    local ServerSection = Acc(tab, "Server Management", true, 2)

    ServerSection:Toggle({
        Title = "Enable Anti-AFK Protection",
        Default = true,
        Flag = "prospecting.server.anti_afk",
        Callback = function(state)
            ServerUtilityModule.setupAntiAFK(state)
        end
    })

    ServerSection:Button({
        Title = "Rejoin Current Server",
        Callback = function()
            ServerUtilityModule.rejoin()
        end
    })

    ServerSection:Button({
        Title = "Server Hop",
        Callback = function()
            ServerUtilityModule.serverHop()
        end
    })

    local EspBox = Acc(tab, "ESP", false, 2)

    EspBox:Toggle({
        Title = "Highlight Players",
        Default = false,
        Flag = "prospecting.esp.players",
        Callback = function(enabled)
            if enabled then
                ESPModule.enablePlayers()
            else
                ESPModule.disablePlayers()
            end
        end
    })

    EspBox:Toggle({
        Title = "Highlight Totems",
        Default = false,
        Flag = "prospecting.esp.totems",
        Callback = function(enabled)
            if enabled then
                ESPModule.enableTotems()
            else
                ESPModule.disableTotems()
            end
        end
    })

    EspBox:Button({
        Title = "Clear All Highlights",
        Callback = function()
            ESPModule.clearAll()
        end
    })

    local InventorySection = Acc(tab, "Inventory", false, 2)

    InventorySection:Toggle({
        Title = "Enable Inventory Filtering",
        Default = true,
        Flag = "prospecting.settings.inventory_filter",
        Callback = function(state)
            if state then
                InventoryFilterModule.create()
            else
                InventoryFilterModule.destroy()
            end
        end
    })
end

initializeMainTab()
initializeHuntingTab()
initializeTeleportTab()
initializeToolsTab()
initializeCraftingTab()
initializeFavouriteTab()
initializeShopTab()
initializeMiscellaneousTab()
